param([string]$BaseUrl="https://krupim-mathlearning.pages.dev")
$ErrorActionPreference="Stop";$base=$BaseUrl.TrimEnd('/');$health=Invoke-WebRequest -UseBasicParsing "$base/api/health" -TimeoutSec 20;if($health.StatusCode-ne 200){throw "Health check failed: $($health.StatusCode)"};$json=$health.Content|ConvertFrom-Json;if($json.status-ne "ok"-or$json.checks.database-ne "ok"){throw "Health response is degraded"};foreach($path in @("/","/learn","/admin")){$response=Invoke-WebRequest -UseBasicParsing "$base$path" -MaximumRedirection 0 -SkipHttpErrorCheck -TimeoutSec 20;if($response.StatusCode-notin @(200,302,303,307,308)){throw "Smoke check $path failed: $($response.StatusCode)"};Write-Host "$path -> $($response.StatusCode)"};Write-Host "Smoke checks passed for $base"
